<script setup lang="ts">import { ref } from 'vue'; defineProps<{ busy:boolean }>(); defineEmits<{ confirm:[reason:string]; cancel:[] }>(); const reason=ref('');</script>
<template><div role="dialog" aria-modal="true" aria-labelledby="delete-title" class="dialog"><h2 id="delete-title">学生を論理削除しますか</h2><p>編集中の変更は保存されません。</p><label>削除理由 ※必須<textarea v-model="reason" maxlength="120"></textarea></label><div class="actions"><button autofocus :disabled="busy" @click="$emit('cancel')">取消</button><button type="button" class="danger" :disabled="busy || !reason.trim()" @click="$emit('confirm',reason)">対象を確認して論理削除</button></div></div></template>
